import json,os
S={}
def add(slug,segs,keys,title,thumb,fs,desc,hash_,tags,verify):
    d=slug; os.makedirs(d,exist_ok=True)
    json.dump([{"text":t,**({"say":s} if s else {})} for t,s in segs],open(d+"/script.json","w"),ensure_ascii=False,indent=1)
    json.dump(keys,open(d+"/keys.json","w"),ensure_ascii=False)
    json.dump({"title":title,"thumb":thumb,"fs":fs,"desc":desc,"tags_hash":hash_,"tags":tags,"verify":verify,"cover_scene":0,"cover_off":1.5},open(d+"/meta.json","w"),ensure_ascii=False,indent=1)
    print(slug,sum(len(t.split()) for t,_ in segs),"palabras")
